<template x-if="page==='projects'&&currentProject"><section class="page-enter">
<div class="page-heading"><div><button class="text-button back-link" @click="go('dashboard')"><span x-html="$icon('ArrowLeft')" class="rotate"></span>خانه</button><h1 x-text="currentProject.name"></h1><p x-text="currentProject.description"></p></div><div class="button-row"><div class="avatar-stack"><template x-for="m in currentProject.members" :key="m.id"><span class="avatar small" :title="m.name"><img x-show="m.avatar_url" :src="m.avatar_url" :alt="m.name"><span x-show="!m.avatar_url" :style="`background:${color(m.id)}`" x-text="initials(m.name)"></span></span></template></div><button class="button primary" x-show="canWrite(currentProject)" @click="openTask()"><span x-html="$icon('Plus')"></span>افزودن تسک</button></div></div>
<div class="goal-card"><div class="goal-main"><div class="goal-kicker"><span x-html="$icon('Target')"></span>هدف اصلی پروژه<span class="status-badge">در یک راستا</span><button class="icon-btn" x-show="isOwner(currentProject)" @click="openGoal()" aria-label="ویرایش هدف" x-html="$icon('Pencil')"></button></div><h2 x-text="currentProject.goal?.title"></h2><p x-text="currentProject.goal?.description"></p><div class="success-criteria"><span x-html="$icon('CheckCircle2')"></span><span><strong>معیار موفقیت:</strong> <span x-text="currentProject.goal?.success_criterion"></span></span></div><div class="goal-dates"><span><span x-html="$icon('CalendarDays')"></span>شروع: <strong x-text="date(currentProject.goal?.start_date)"></strong></span><span>مقصد: <strong x-text="date(currentProject.goal?.target_date)"></strong></span></div></div><div class="goal-progress"><div class="progress-ring" :style="`--progress:${progress(currentProject)}%`"><strong x-text="fa(progress(currentProject))+'٪'"></strong></div><strong>در مسیر هدف</strong><small x-text="fa(tasks.filter(t=>t.project_id===projectId&&t.completed_at).length)+' از '+fa(tasks.filter(t=>t.project_id===projectId).length)+' تسک تکمیل شده'"></small></div></div>
<div class="section-heading stage-heading"><div><h2>مراحل محصول <span class="count-badge" x-text="fa(currentProject.stages.length)"></span></h2><p>مسیر رسیدن به هدف، قدم به قدم</p></div><x-ui-select model="taskFilter" options="[{value:'active',label:'تسک‌های باز'},{value:'all',label:'همه تسک‌ها'},{value:'done',label:'تکمیل‌شده‌ها'}]" placeholder="تسک‌های باز" /></div>
<div class="board product-board">
<template x-for="s in currentProject.stages" :key="s.id"><section class="board-column" @dragover.prevent @drop.prevent="taskDrag?dropTaskOnProductStage(s):reorderStage(s)">
    <div class="stage-column-head" :draggable="canWrite(currentProject)&&!taskDrag" @dragstart="dragStage=s.id;$event.dataTransfer.effectAllowed='move'" @dragend="dragStage=null">
        <div class="stage-title-wrap">
            <form class="inline-column-rename" x-show="columnRename?.id===s.id&&columnRename?.kind==='product'" @submit.prevent="saveColumnRename(s,'product',currentProject)" @keydown.escape.prevent="cancelColumnRename()"><input data-column-rename-input x-model="columnRenameTitle" maxlength="120"></form>
            <template x-if="!(columnRename?.id===s.id&&columnRename?.kind==='product')"><h3 x-text="s.title"></h3></template>
            <span class="column-count" x-text="fa(stageTotal(s.id))"></span>
        </div>
        <div x-data="{open:false}" class="stage-menu" @click.outside="open=false"><button class="icon-btn" @click="open=!open" :aria-label="'گزینه‌های '+s.title" x-html="$icon('MoreHorizontal')"></button><div class="dropdown-menu" x-show="open" x-transition.opacity.scale.95.duration.150ms><button @click="beginColumnRename(s,'product',currentProject);open=false">تغییر نام</button><button @click="openStage(s,null,currentProject);open=false">تنظیم تاریخ</button><button class="danger-text" @click="deleteStage(s,'product');open=false">حذف ستون</button></div></div>
    </div>
    <div class="column-tasks"><template x-for="t in stageTasks(s.id)" :key="t.id">@include('partials.task-card')</template></div>
    <button class="add-column-task" x-show="canWrite(currentProject)" @click="openTask(null,s,currentProject)"><span class="add-task-plus"><span x-html="$icon('Plus')"></span></span><span>افزودن تسک</span></button>
</section></template>
<section class="board-column add-column-card" :class="{'is-editing':inlineColumn?.kind==='product'&&inlineColumn?.project_id===currentProject.id}" x-show="canWrite(currentProject)">
    <button class="add-column-trigger" x-show="inlineColumn?.kind!=='product'||inlineColumn?.project_id!==currentProject.id" @click="startInlineColumn('product',currentProject)"><span x-html="$icon('Plus')"></span><span>افزودن ستون</span></button>
    <form class="column-create-form" x-show="inlineColumn?.kind==='product'&&inlineColumn?.project_id===currentProject.id" @submit.prevent="saveInlineColumn('product',currentProject)" @keydown.escape.prevent="cancelInlineColumn()">
        <input data-inline-column-input x-model="inlineColumnForm.title" placeholder="نام این ستون" maxlength="120">
        <textarea x-model="inlineColumnForm.description" placeholder="توضیحات (اختیاری)" rows="3" maxlength="2000"></textarea>
        <div class="column-create-actions"><button class="button primary small-button" type="submit" :disabled="!inlineColumnForm.title.trim()">افزودن ستون</button><button class="text-button" type="button" @click="cancelInlineColumn()">انصراف</button></div>
    </form>
</section>
</div>
<div class="section-heading team-heading"><div><h2>مسیر اعضای تیم</h2><p>مسیرهای متفاوت، به سوی یک هدف مشترک</p></div><span class="subtle-label"><span x-html="$icon('Users')"></span><span x-text="fa(currentProject.members.length)+' عضو تیم'"></span></span></div><div class="team-grid"><template x-for="m in currentProject.members" :key="m.id"><article class="team-card"><div class="team-card-head"><span class="avatar"><img x-show="m.avatar_url" :src="m.avatar_url" :alt="m.name"><span x-show="!m.avatar_url" :style="`background:${color(m.id)}`" x-text="initials(m.name)"></span></span><div><strong x-text="m.name"></strong><small x-text="m.job_title||'عضو تیم'"></small></div></div><div class="team-stages"><template x-for="(s,i) in currentProject.member_stages.filter(s=>s.member_id===m.id)" :key="s.id"><div class="team-stage" :draggable="canWrite(currentProject)" @dragstart.stop="teamDrag=s.id" @dragover.prevent @drop.stop.prevent="reorderStage(s,'member',m)"><span class="step-number" x-text="fa(i+1)"></span><button @click="openStage(s,m,currentProject)" x-text="s.title"></button><button class="icon-btn" x-show="canWrite(currentProject)" @click="moveStage(s,-1,'member',m)" aria-label="جابجایی به قبل" x-html="$icon('GripVertical')"></button></div></template><p class="muted" x-show="!currentProject.member_stages.some(s=>s.member_id===m.id)">مسیر این عضو هنوز تعریف نشده است.</p></div></article></template></div>
</section></template>
<div class="empty-state page-enter" x-show="page==='projects'&&projectId&&!currentProject&&!loading"><h2>پروژه در دسترس نیست</h2><button class="button" @click="go('dashboard')">بازگشت به خانه</button></div>
